-- Removes everything demo-data.sql created: the demo church (its services,
-- classes, codes, points, posts… cascade with it) and the demo accounts.
-- Real accounts and anything else are left alone. Safe to run twice.
begin;

delete from public.churches where id = '10000000-0000-4000-a000-000000000001';

delete from auth.users
where id in (
  '00000000-0000-4000-a000-000000000002',
  '00000000-0000-4000-a000-000000000003',
  '00000000-0000-4000-b000-000000000001',
  '00000000-0000-4000-b000-000000000002',
  '00000000-0000-4000-c000-000000000001',
  '00000000-0000-4000-c000-000000000002',
  '00000000-0000-4000-c000-000000000003',
  '00000000-0000-4000-c000-000000000004',
  '00000000-0000-4000-c000-000000000005',
  '00000000-0000-4000-c000-000000000006',
  '00000000-0000-4000-c000-000000000007',
  '00000000-0000-4000-c000-000000000008'
);

commit;
